module.exports = "import React, { Fragment } from 'react';\n\nimport {\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiTitle,\n  EuiSpacer,\n} from '../../../../src/components';\n\nimport { palettes } from '../../../../src/services';\n\nconst paletteData = palettes;\nconst paletteNames = Object.keys(paletteData);\n\nexport default () => (\n  <Fragment>\n    {paletteNames.map((paletteName, i) => (\n      <div key={paletteName}>\n        <EuiTitle key={i} size=\"xxs\">\n          <h3>{paletteName}</h3>\n        </EuiTitle>\n        <EuiSpacer size=\"s\" />\n        <EuiFlexGroup\n          gutterSize=\"none\"\n          alignItems=\"flexStart\"\n          key={`${paletteName}-${i}`}>\n          {paletteData[paletteName].colors.map((hexCode, j) => (\n            <EuiFlexItem\n              key={`${hexCode}-${j}`}\n              grow={false}\n              className={'guideColorPalette__swatch'}>\n              <span title={hexCode} style={{ backgroundColor: hexCode }} />\n            </EuiFlexItem>\n          ))}\n        </EuiFlexGroup>\n        <EuiSpacer size=\"l\" />\n      </div>\n    ))}\n  </Fragment>\n);\n"