module.exports = "import React, { Component } from 'react';\n\nimport PropTypes from 'prop-types';\n\nimport moment from 'moment';\n\nimport { EuiDatePicker, EuiButton } from '../../../../src/components';\n\n// Should be a component because the date picker does some ref stuff behind the scenes\n// eslint-disable-next-line react/prefer-stateless-function\nclass ExampleCustomInput extends React.Component {\n  render() {\n    return (\n      <EuiButton className=\"example-custom-input\" onClick={this.props.onClick}>\n        {this.props.value}\n      </EuiButton>\n    );\n  }\n}\n\nExampleCustomInput.propTypes = {\n  onClick: PropTypes.func,\n  value: PropTypes.string,\n};\n\n// eslint-disable-next-line react/no-multi-comp\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: moment(),\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date,\n    });\n  }\n\n  render() {\n    return (\n      <EuiDatePicker\n        selected={this.state.startDate}\n        onChange={this.handleChange}\n        customInput={<ExampleCustomInput />}\n      />\n    );\n  }\n}\n"